function parseLocalDateTime(s) {
  const [d, t = "00:00:00"] = s.split("T");
  const [y, m, day] = d.split("-").map(Number);
  const [h, mi, sec = "0"] = t.split(":");
  return new Date(y, m - 1, day, Number(h), Number(mi), Math.floor(Number(sec)));
}

